INSERT INTO documents (title,subject,content,source_page) VALUES ('Python - Variables and Data Types Notes','Python','Variables and Data Types: A variable stores a value that can be used by a program. These notes provide introductory educational material for students studying Python.','Page 5');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Python - Functions Notes','Python','Functions: A function is a reusable block of code defined with the def keyword. These notes provide introductory educational material for students studying Python.','Page 6');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Python - Object Oriented Programming Notes','Python','Object Oriented Programming: Object oriented programming organizes programs around classes and objects. These notes provide introductory educational material for students studying Python.','Page 7');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Python - Exception Handling Notes','Python','Exception Handling: Exception handling manages runtime errors using mechanisms such as try and except. These notes provide introductory educational material for students studying Python.','Page 8');
INSERT INTO documents (title,subject,content,source_page) VALUES ('DBMS - SQL Joins Notes','DBMS','SQL Joins: SQL joins combine rows from two or more tables using related columns. These notes provide introductory educational material for students studying DBMS.','Page 9');
INSERT INTO documents (title,subject,content,source_page) VALUES ('DBMS - Normalization Notes','DBMS','Normalization: Normalization reduces data redundancy and improves data integrity. These notes provide introductory educational material for students studying DBMS.','Page 10');
INSERT INTO documents (title,subject,content,source_page) VALUES ('DBMS - Transactions Notes','DBMS','Transactions: A transaction is a logical unit of database work governed by properties such as ACID. These notes provide introductory educational material for students studying DBMS.','Page 11');
INSERT INTO documents (title,subject,content,source_page) VALUES ('DBMS - Indexes Notes','DBMS','Indexes: An index is a database structure that can speed up data retrieval. These notes provide introductory educational material for students studying DBMS.','Page 12');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Data Structures - Arrays Notes','Data Structures','Arrays: An array stores elements in an indexed collection. These notes provide introductory educational material for students studying Data Structures.','Page 13');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Data Structures - Linked Lists Notes','Data Structures','Linked Lists: A linked list stores nodes connected through links or references. These notes provide introductory educational material for students studying Data Structures.','Page 14');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Data Structures - Stacks Notes','Data Structures','Stacks: A stack follows the last-in-first-out principle. These notes provide introductory educational material for students studying Data Structures.','Page 15');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Data Structures - Queues Notes','Data Structures','Queues: A queue generally follows the first-in-first-out principle. These notes provide introductory educational material for students studying Data Structures.','Page 16');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Machine Learning - Classification Notes','Machine Learning','Classification: Classification predicts a category or class from input data. These notes provide introductory educational material for students studying Machine Learning.','Page 17');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Machine Learning - Regression Notes','Machine Learning','Regression: Regression predicts a continuous numerical value. These notes provide introductory educational material for students studying Machine Learning.','Page 18');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Machine Learning - Clustering Notes','Machine Learning','Clustering: Clustering groups similar data points without predefined class labels. These notes provide introductory educational material for students studying Machine Learning.','Page 19');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Machine Learning - Model Evaluation Notes','Machine Learning','Model Evaluation: Model evaluation measures how well a machine learning model performs. These notes provide introductory educational material for students studying Machine Learning.','Page 20');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Artificial Intelligence - Search Algorithms Notes','Artificial Intelligence','Search Algorithms: Search algorithms explore possible states to find a solution. These notes provide introductory educational material for students studying Artificial Intelligence.','Page 21');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Artificial Intelligence - Knowledge Representation Notes','Artificial Intelligence','Knowledge Representation: Knowledge representation encodes information so an AI system can reason with it. These notes provide introductory educational material for students studying Artificial Intelligence.','Page 22');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Artificial Intelligence - Natural Language Processing Notes','Artificial Intelligence','Natural Language Processing: Natural language processing deals with computational processing of human language. These notes provide introductory educational material for students studying Artificial Intelligence.','Page 23');
INSERT INTO documents (title,subject,content,source_page) VALUES ('Artificial Intelligence - Intelligent Agents Notes','Artificial Intelligence','Intelligent Agents: An intelligent agent perceives its environment and acts toward goals. These notes provide introductory educational material for students studying Artificial Intelligence.','Page 24');
